'::text WHERE
idashboardqueryid = 62 AND itenantid in (14,15);

---rule efficiency report
UPDATE ui.dashboardquery SET
vcdashboardquery = 'select rp.tdate as "Date", d.vcdecisionname as "Decision", rp.vcclassname as "Class", rp.iruleid as "Rule ID",  r.vcrulename as "Rule Name",
rp.score as "Score", rp.scoretxncount as "Rule Triggered Count", rp.totaltxncount as "Total Txn Count",
round( cast((cast(rp.scoretxncount as float)* 100)/rp.totaltxncount as numeric	),2	) as "Rule Efficiency (%)",
round( cast((cast(rp.override_txncount as float)* 100)/rp.scoretxncount as numeric	),2	) as "False Alert %",
rp.scoretxnvalue / rp.scoretxncount as "Avg Value (Rules Triggered)",
rp.totaltxnvalue / rp.totaltxncount as "Avg Value (Total Txns)",
rp.accounts_affected as "Unique Accounts Triggered",
rp.vpas_affected as "Unique VPAs Affected"
from analytics.rule_performance rp
left join masters.rules r on r.iruleid = rp.iruleid
left join masters.decisions d on d.idecisionid = rp.idecisionid where tdate  between cast(:StartDate as date) and cast(:EndDate as date) and score > 0 
and rp.itenantid=:tenantid limit 10000;'::text WHERE
idashboardqueryid = 31 AND itenantid  in (14, 15);

-----Acc wise rule triggered
UPDATE ui.dashboardquery SET
vcdashboardquery =  E'{
    "All":
    {
        "All" : { 
            "All" : "SELECT \\"Txn Date Time\\", \\"Txn ID\\", \\"Unique ID\\", \\"Payer Customer ID\\", \\"Payer Account ID\\", \\"Payer VPA ID\\",\\"Customer ID\\", \\"Account ID\\", \\"VPA ID\\", \\"Payee Customer ID\\", \\"Payee Account ID\\", \\"Payee VPA ID\\", \\"Txn Class\\", \\"Txn Amount\\", \\"Decision Name\\", \\"Rule ID\\", \\"Rule Name\\", \\"Score\\", \\"Side\\" FROM analytics.combined_rule_triggered WHERE \\"Tenant ID\\" = :tenantid AND \\"Txn Class\\" in (with d1 as (select mappingid from ui.webusermapping where webuserid = :loggedinuser AND iorgid =:orgid  and mappingtype = ''TransactionClass'') (select vcclassname FROM ui.transactionclasses where (iclassid in (select mappingid from d1) or -1 in (select mappingid from d1)) and itenantid=:tenantid)) AND \\"Score\\" >= :score AND \\"Txn Date Time\\" BETWEEN :StartDate AND :EndDate limit 50000",
            "Other": "SELECT \\"Txn Date Time\\", \\"Txn ID\\", \\"Unique ID\\", \\"Payer Customer ID\\", \\"Payer Account ID\\", \\"Payer VPA ID\\",\\"Customer ID\\", \\"Account ID\\", \\"VPA ID\\", \\"Payee Customer ID\\", \\"Payee Account ID\\", \\"Payee VPA ID\\", \\"Txn Class\\", \\"Txn Amount\\", \\"Decision Name\\", \\"Rule ID\\", \\"Rule Name\\", \\"Score\\", \\"Side\\" FROM analytics.combined_rule_triggered WHERE \\"Tenant ID\\" = :tenantid AND \\"Txn Class\\" in (with d1 as (select mappingid from ui.webusermapping where webuserid = :loggedinuser AND iorgid =:orgid  and mappingtype = ''TransactionClass'') (select vcclassname FROM ui.transactionclasses where (iclassid in (select mappingid from d1) or -1 in (select mappingid from d1)) and itenantid=:tenantid)) AND \\"Score\\" >= :score AND \\"Txn Date Time\\" BETWEEN :StartDate AND :EndDate and \\"Rule Name\\" = :rule limit 50000"
        },
        "Other": {
