            "Other": "SELECT \\"Txn Date Time\\", \\"Txn ID\\", \\"Unique ID\\", \\"Payer Customer ID\\", \\"Payer Account ID\\", \\"Payer VPA ID\\",\\"Customer ID\\", \\"Account ID\\", \\"VPA ID\\", \\"Payee Customer ID\\", \\"Payee Account ID\\", \\"Payee VPA ID\\", \\"Txn Class\\", \\"Txn Amount\\", \\"Decision Name\\", \\"Rule ID\\", \\"Rule Name\\", \\"Score\\", \\"Side\\" FROM analytics.combined_rule_triggered WHERE \\"Tenant ID\\" = :tenantid AND \\"Txn Class\\" in (with d1 as (select mappingid from ui.webusermapping where webuserid = :loggedinuser AND iorgid =:orgid  and mappingtype = ''TransactionClass'') (select vcclassname FROM ui.transactionclasses where (iclassid in (select mappingid from d1) or -1 in (select mappingid from d1)) and itenantid=:tenantid)) AND \\"Score\\" >= :score AND \\"Txn Date Time\\" BETWEEN :StartDate AND :EndDate and \\"Decision Name\\" = :decision and \\"Rule Name\\" = :rule limit 50000"
        }
