            "Other": "SELECT \\"Txn Date Time\\", \\"Txn ID\\", \\"Unique ID\\", \\"Payer Customer ID\\", \\"Payer Account ID\\", \\"Payer VPA ID\\",\\"Customer ID\\", \\"Account ID\\", \\"VPA ID\\", \\"Payee Customer ID\\", \\"Payee Account ID\\", \\"Payee VPA ID\\", \\"Txn Class\\", \\"Txn Amount\\", \\"Decision Name\\", \\"Rule ID\\", \\"Rule Name\\", \\"Score\\", \\"Side\\" FROM analytics.combined_rule_triggered WHERE \\"Tenant ID\\" = :tenantid AND \\"Score\\" >= :score AND \\"Txn Date Time\\" BETWEEN :StartDate AND :EndDate and \\"Rule Name\\" = :rule and \\"Txn Class\\" = :class limit 50000"
        },
