UPDATE ui.dashboardquery SET
vcdashboardquery =  E'    {
        "Account": {
             "Monthly": "WITH  RECURSIVE profile AS ( SELECT pv.iaccountid, pv.tdate, pv.val || cast( format( ''{\\"Address\\":\\"%s\\",\\"Name\\":\\"%s\\", \\"Last Update\\":\\"%s\\"}'', vcexternalaccountid, vcaccountname, last_updated ) as jsonb ) as val FROM profiles.account_monthly pv LEFT JOIN masters.accounts v ON v.iaccountid = pv.iaccountid and v.itenantid=:tenantid WHERE tdate BETWEEN cast(:StartDate as date) AND cast(:EndDate as date) - 1 AND v.vcexternalaccountid = :Address ), flat (iaccountid, tdate, key, value) AS ( SELECT iaccountid, tdate, concat('''', key), value FROM profile, jsonb_each(val) UNION SELECT iaccountid, tdate, concat(f.key, ''.'', j.key), j.value FROM flat f, jsonb_each(f.value) j WHERE jsonb_typeof(f.value) = ''object'' ) SELECT cast(json_agg(data) as text) FROM ( SELECT iaccountid, tdate, jsonb_object_agg( COALESCE(metadata.vccolumnname, flat.key), value ) AS data FROM flat LEFT JOIN profiles.metadata ON metadata.vcpath = flat.key AND metadata.vcroot = ''account_monthly'' AND metadata.itenantid=:tenantid WHERE jsonb_typeof(value) <> ''object'' GROUP BY iaccountid, tdate ) a limit 1000;",
           "Weekly": "WITH  RECURSIVE profile AS ( SELECT pv.iaccountid, pv.tdate, pv.val || cast( format( ''{\\"Address\\":\\"%s\\",\\"Name\\":\\"%s\\", \\"Last Update\\":\\"%s\\"}'', vcexternalaccountid, vcaccountname, last_updated ) as jsonb ) as val FROM profiles.account_weekly pv LEFT JOIN masters.accounts v ON v.iaccountid = pv.iaccountid and v.itenantid=:tenantid WHERE tdate BETWEEN cast(:StartDate as date) AND cast(:EndDate as date) - 1 AND v.vcexternalaccountid = :Address ), flat (iaccountid, tdate, key, value) AS ( SELECT iaccountid, tdate, concat('''', key), value FROM profile, jsonb_each(val) UNION SELECT iaccountid, tdate, concat(f.key, ''.'', j.key), j.value FROM flat f, jsonb_each(f.value) j WHERE jsonb_typeof(f.value) = ''object'' ) SELECT cast(json_agg(data) as text) FROM ( SELECT iaccountid, tdate, jsonb_object_agg( COALESCE(metadata.vccolumnname, flat.key), value ) AS data FROM flat LEFT JOIN profiles.metadata ON metadata.vcpath = flat.key AND metadata.vcroot = ''account_weekly'' AND metadata.itenantid=:tenantid WHERE jsonb_typeof(value) <> ''object'' GROUP BY iaccountid, tdate ) a limit 1000;"
        },
        "VPA": {
             "Monthly": "WITH RECURSIVE profile AS ( SELECT pv.ivpaid, pv.tdate, pv.val || cast( format( ''{\\"Address\\":\\"%s\\",\\"Name\\":\\"%s\\", \\"Last Update\\":\\"%s\\"}'', vcexternaladdressid, vcvpaname, last_updated ) as jsonb ) as val FROM profiles.vpa_monthly pv LEFT JOIN masters.vpa v ON v.ivpaid = pv.ivpaid and v.itenantid=:tenantid WHERE tdate BETWEEN cast(:StartDate as date) AND cast(:EndDate as date) - 1 AND v.vcexternaladdressid = :Address ), flat (ivpaid, tdate, key, value) AS ( SELECT ivpaid, tdate, concat('''', key), value FROM profile, jsonb_each(val) UNION SELECT ivpaid, tdate, concat(f.key, ''.'', j.key), j.value FROM flat f, jsonb_each(f.value) j WHERE jsonb_typeof(f.value) = ''object'' ) SELECT cast(json_agg(data) as text) FROM ( SELECT ivpaid, tdate, jsonb_object_agg( COALESCE(metadata.vccolumnname, flat.key), value ) AS data FROM flat LEFT JOIN profiles.metadata ON metadata.vcpath = flat.key AND metadata.vcroot = ''vpa_monthly'' AND metadata.itenantid=:tenantid WHERE jsonb_typeof(value) <> ''object'' GROUP BY ivpaid, tdate ) a limit 1000;",
           "Weekly": "WITH RECURSIVE profile AS ( SELECT pv.ivpaid, pv.tdate, pv.val || cast( format( ''{\\"Address\\":\\"%s\\",\\"Name\\":\\"%s\\", \\"Last Update\\":\\"%s\\"}'', vcexternaladdressid, vcvpaname, last_updated ) as jsonb ) as val FROM profiles.vpa_weekly pv LEFT JOIN masters.vpa v ON v.ivpaid = pv.ivpaid and v.itenantid=:tenantid WHERE tdate BETWEEN cast(:StartDate as date) AND cast(:EndDate as date) - 1 AND v.vcexternaladdressid = :Address ), flat (ivpaid, tdate, key, value) AS ( SELECT ivpaid, tdate, concat('''', key), value FROM profile, jsonb_each(val) UNION SELECT ivpaid, tdate, concat(f.key, ''.'', j.key), j.value FROM flat f, jsonb_each(f.value) j WHERE jsonb_typeof(f.value) = ''object'' ) SELECT cast(json_agg(data) as text) FROM ( SELECT ivpaid, tdate, jsonb_object_agg( COALESCE(metadata.vccolumnname, flat.key), value ) AS data FROM flat LEFT JOIN profiles.metadata ON metadata.vcpath = flat.key AND metadata.vcroot = ''vpa_weekly'' AND metadata.itenantid=:tenantid WHERE jsonb_typeof(value) <> ''object'' GROUP BY ivpaid, tdate ) a limit 1000;"
        }
    }'::text WHERE
idashboardqueryid = 65 and itenantid not in (14, 15);

---reports
--pendency report

UPDATE ui.dashboardquery SET
vcdashboardquery = 'SELECT string_agg (DISTINCT grp.name_, '', '') as "Group Name",
cuser.email_ as "Analyst Name",
count(distinct CASE
WHEN DATE_PART(''day'', current_timestamp -  CASE
WHEN  oplog.timestamp_ is not null THEN oplog.timestamp_
WHEN  oplog.timestamp_ is null THEN task.create_time_
ELSE null END ) > 30 THEN task.proc_inst_id_
ELSE null
END) as "Above 30 days",
count(distinct CASE
WHEN DATE_PART(''day'', current_timestamp -  CASE
WHEN  oplog.timestamp_ is not null THEN oplog.timestamp_
WHEN  oplog.timestamp_ is null THEN task.create_time_
ELSE null END ) between 20 and 30 THEN task.proc_inst_id_
ELSE null
END) as "30 days to 20 days",
count(distinct CASE
WHEN DATE_PART(''day'', current_timestamp -  CASE
WHEN  oplog.timestamp_ is not null THEN oplog.timestamp_
WHEN  oplog.timestamp_ is null THEN task.create_time_
ELSE null END ) between 10 and 20 THEN task.proc_inst_id_
ELSE null
END) as "20 days to 10 days",
count(distinct CASE
WHEN DATE_PART(''day'', current_timestamp -  CASE
WHEN  oplog.timestamp_ is not null THEN oplog.timestamp_
WHEN  oplog.timestamp_ is null THEN task.create_time_
ELSE null END ) < 10 THEN task.proc_inst_id_
ELSE null
END) as "below 10 days"
FROM
camunda.act_ru_task task
right join camunda.act_re_procdef pdef on task.proc_def_id_ = pdef.id_
full outer join camunda.act_hi_identitylink oplog on oplog.id_ = (select id_ from camunda.act_hi_identitylink where task_id_ = task.id_ and type_ = ''assignee'' and user_id_ = task.assignee_ order by timestamp_ desc limit 1)
right join camunda.act_id_user cuser on task.assignee_ = cuser.id_
right join camunda.act_id_membership memb on task.assignee_ = memb.user_id_
right join camunda.act_hi_identitylink idl on idl.task_id_ = task.id_ and idl.type_= ''candidate''
left join camunda.act_id_group grp on grp.id_ = idl.group_id_ and grp.id_ = memb.group_id_
where task.assignee_ is not null and task.tenant_id_ = :tenantidstr
group by cuser.id_
order by string_agg(DISTINCT grp.name_, '', '') asc limit 1000'::text WHERE
idashboardqueryid = 59 and itenantid in (14, 15);

---daily productivity report
UPDATE ui.dashboardquery SET
vcdashboardquery =  E'{
    "All":"WITH raw AS ( SELECT hiproc.proc_inst_id_ AS \\"procid\\", hitask.end_time_ AS \\"endtime\\", hitask.id_ AS \\"taskid\\", hiproc.state_ AS \\"state\\", assignee.email_ AS \\"assignee\\", hitask.name_ AS \\"taskname\\", grup.vcgroupname AS \\"groupname\\", workflow.workflowname as \\"workflowname\\" FROM camunda.act_hi_taskinst hitask LEFT JOIN camunda.act_hi_procinst hiproc ON hiproc.proc_inst_id_ = hitask.proc_inst_id_ LEFT JOIN camunda.act_hi_detail hidetail ON hidetail.name_ = ''userActivity'' AND hitask.assignee_ IS NOT NULL AND hitask.end_time_ IS NULL AND hidetail.proc_inst_id_ = hiproc.proc_inst_id_ LEFT JOIN camunda.act_id_user assignee ON assignee.id_ = hitask.assignee_ LEFT JOIN ui.webusermapping groupmembership ON cast(groupmembership.webuserid as text) = assignee.id_ and groupmembership.mappingtype = ''Group'' and groupmembership.mappingid != 1 and groupmembership.itenantid = :tenantid LEFT JOIN ui.groupdesc grup ON grup.igroupid = groupmembership.mappingid LEFT JOIN ui.workflowmasters workflow on workflow.workflowkey = hiproc.proc_def_key_ and workflow.itenantid = :tenantid WHERE (CAST(hitask.end_time_ AS date) = :Date OR CAST(hidetail.time_ AS date) = :Date ) AND hitask.proc_def_key_ in (with d1 as (select mappingid from ui.webusermapping where webuserid = :loggedinuser and mappingtype = ''Workflow'') (select workflowkey FROM ui.workflowmasters where (workflowid in (select mappingid from d1) or -1 in (select mappingid from d1)) and itenantid=:tenantid and is_filter_display=true)) AND hiproc.state_ != ''EXTERNALLY_TERMINATED'' AND hitask.assignee_ IS NOT NULL and hiproc.tenant_id_ = :tenantidstr ) SELECT org.assignee AS \\"Analyst\\", STRING_AGG(distinct org.groupname, '', '') AS \\"User Group\\", org.taskname as \\"Stage Name\\", count(distinct case when org.endtime is not null then org.taskid else null end) as \\"Cases Submitted\\", count(distinct case when org.endtime is null then org.taskid else null end) as \\"Claimed\\", count(distinct closedby.taskid) as \\"Total Cases - Closed\\", org.workflowname as \\"Workflow Name\\" FROM raw org LEFT JOIN raw closedby ON closedby.taskid = ( SELECT taskid FROM raw WHERE procid = org.procid AND state = ''COMPLETED'' ORDER BY endtime DESC LIMIT 1 ) and closedby.taskid = org.taskid AND closedby.state = ''COMPLETED'' GROUP BY org.assignee, org.taskname, org.workflowname limit 1000;",
    "Other":"WITH raw AS ( SELECT hiproc.proc_inst_id_ AS \\"procid\\", hitask.end_time_ AS \\"endtime\\", hitask.id_ AS \\"taskid\\", hiproc.state_ AS \\"state\\", assignee.email_ AS \\"assignee\\", hitask.name_ AS \\"taskname\\", grup.vcgroupname AS \\"groupname\\", workflow.workflowname as \\"workflowname\\" FROM camunda.act_hi_taskinst hitask LEFT JOIN camunda.act_hi_procinst hiproc ON hiproc.proc_inst_id_ = hitask.proc_inst_id_ LEFT JOIN camunda.act_hi_detail hidetail ON hidetail.name_ = ''userActivity'' AND hitask.assignee_ IS NOT NULL AND hitask.end_time_ IS NULL AND hidetail.proc_inst_id_ = hiproc.proc_inst_id_ LEFT JOIN camunda.act_id_user assignee ON assignee.id_ = hitask.assignee_ LEFT JOIN ui.webusermapping groupmembership ON cast(groupmembership.webuserid as text) = assignee.id_ and groupmembership.mappingtype = ''Group'' and groupmembership.mappingid != 1 and groupmembership.itenantid = :tenantid LEFT JOIN ui.groupdesc grup ON grup.igroupid = groupmembership.mappingid LEFT JOIN ui.workflowmasters workflow on workflow.workflowkey = hiproc.proc_def_key_ and workflow.itenantid = :tenantid WHERE (CAST(hitask.end_time_ AS date) = :Date OR CAST(hidetail.time_ AS date) = :Date ) AND hitask.proc_def_key_ = :CaseType AND hiproc.state_ != ''EXTERNALLY_TERMINATED'' AND hitask.assignee_ IS NOT NULL and hiproc.tenant_id_ = :tenantidstr ) SELECT org.assignee AS \\"Analyst\\", STRING_AGG(distinct org.groupname, '', '') AS \\"User Group\\", org.taskname as \\"Stage Name\\", count(distinct case when org.endtime is not null then org.taskid else null end) as \\"Cases Submitted\\", count(distinct case when org.endtime is null then org.taskid else null end) as \\"Claimed\\", count(distinct closedby.taskid) as \\"Total Cases - Closed\\", org.workflowname as \\"Workflow Name\\" FROM raw org LEFT JOIN raw closedby ON closedby.taskid = ( SELECT taskid FROM raw WHERE procid = org.procid AND state = ''COMPLETED'' ORDER BY endtime DESC LIMIT 1 ) and closedby.taskid = org.taskid AND closedby.state = ''COMPLETED'' GROUP BY org.assignee, org.taskname, org.workflowname limit 1000;"

}'::text WHERE
idashboardqueryid = 60 AND itenantid in (14, 15);


----txn count report

UPDATE ui.dashboardquery SET
vcdashboardquery = 'SELECT "Date",
"Class",
SUM ("Txns Failed to Process") AS "Txns Failed to Process",
SUM("Txns Processed Successfully") AS "Txns Processed Successfully" ,
SUM("Txns Failed to Process") + SUM("Txns Processed Successfully") AS "Txn Requests Received"
FROM
(select
date(sr.dtentrydatetime) as "Date",
cast(vcrequestdata as json)->''txn''->>''class'' as "Class",
case when sr.vcrequestid is null then 0 else 1 end  as "Txns Failed to Process",
case when sr.vcrequestid is null then 1 else 0 end  as "Txns Processed Successfully"
from
analytics.scorerequests sr
WHERE sr.dtentrydatetime between :StartDate and :EndDate and sr.itenantid = :tenantid
UNION ALL
select
date(tx.dttrxntime) as "Date",
tx.vcclassname as "Class",
case when tx.vcmsgid is null then 1 else 0 end  as "Txns Failed to Process",
case when tx.vcmsgid is null then 0 else 1 end  as "Txns Processed Successfully"
from
analytics.trans tx
WHERE tx.dttrxntime between :StartDate and :EndDate and tx.itenantid = :tenantid
 ) T GROUP BY "Date",
"Class" limit 10000;'::text WHERE
idashboardqueryid = 80 and itenantid in (14, 15);


---audit report rules

UPDATE ui.dashboardquery SET
vcdashboardquery = 'SELECT d.vcdecisionname as "Decision Name", r.iruleid as "Rule ID", r.vcrulename as "Rule Name", makeruser.vcusername as "Maker User", r.dtentrystamp  as "Maker Time Stamp", r.vcremark as "Maker & Checker Remarks", checkeruser.vcusername as "Checker User", r.dtapproverstamp  as "Checker Time Stamp", case when r.vcaction = ''A'' then ''Add'' when r.vcaction = ''M'' then ''Modify'' when r.vcaction = ''X'' then ''Delete'' when r.vcaction = ''N'' then ''No Change'' end as "Action", iversion as "Rule Version", vclabel as "Rule Label", vcruledescription as "Rule Description", vcruledetail as "Rule Detail", vcruleparams as "Rule Params", vcruleorder as "Rule Order" FROM ui.rulesaudit r inner join ui.decisions d on r.idecisionid = d.idecisionid  left join ui.webuser makeruser on makeruser.iuserid = r.ientryuserid left join ui.webuser checkeruser on checkeruser.iuserid = r.iapproveruserid where d.itenantid = :tenantid and cast(r.dtentrystamp as date) between cast(:StartDate as date) and cast(:EndDate as date) limit 10000;'::text WHERE
idashboardqueryid = 82 and itenantid in (14, 15);

-- audit report class

UPDATE ui.dashboardquery SET
vcdashboardquery = 'SELECT r.vcclassname as "Class Name", r.iclassid as "Class ID",  d.vcdecisionname as "Decision Name", p.vcproductname as "Product Name", c.vcchannelname as "Channel Name", makeruser.vcusername as "Maker User", r.dtentrystamp  as "Maker Time Stamp", r.vcremark as "Maker & Checker Remarks", checkeruser.vcusername as "Checker User", r.dtapproverstamp  as "Checker Time Stamp", case when r.vcaction = ''A'' then ''Add'' when r.vcaction = ''M'' then ''Modify'' when r.vcaction = ''X'' then ''Delete'' when r.vcaction = ''N'' then ''No Change'' end as "Action", r.bpayeemandatory as "Payee Mandatory", r.bpayermandatory  as "Payer Mandatory", cast(r.vcdecisionparams as text)   as "Decision Parameters", r.skipprocessing   as "Skip Processing", cast(r.attribs as text) as "Attribs" FROM ui.transactionclassesaudit r left join ui.decisions d on r.idecisionid = d.idecisionid left join masters.products p on r.iproductid = p.iproductid left join masters.channels c on r.ichannelid = c.ichannelid left join ui.webuser makeruser on makeruser.iuserid = r.ientryuserid left join ui.webuser checkeruser on checkeruser.iuserid = r.iapproveruserid where r.itenantid = :tenantid and cast(r.dtentrystamp as date) between cast(:StartDate as date) and cast(:EndDate as date) limit 10000;'::text WHERE
idashboardqueryid = 83 and itenantid in (14, 15);


--audit report decision

UPDATE ui.dashboardquery SET
vcdashboardquery = 'SELECT r.vcdecisionname as "Decision Name", r.vcdecisiondetail  as "Decision Description",  r.idecisionid as "Decision ID", makeruser.vcusername as "Maker User", r.dtentrystamp  as "Maker Time Stamp", r.vcremark as "Maker & Checker Remarks", checkeruser.vcusername as "Checker User", r.dtapproverstamp  as "Checker Time Stamp", case when r.vcaction = ''A'' then ''Add'' when r.vcaction = ''M'' then ''Modify'' when r.vcaction = ''X'' then ''Delete'' when r.vcaction = ''N'' then ''No Change'' end as "Action", cast(r.vcresultparams as text) as "Decision Parameters", p.vcproductname as "Product Name", cast(r.attribs as text) as "Attributes", r.vcdecisionmapinfo as "Decision Info" FROM ui.decisionsworkflowaudit r left join masters.products p on r.iproductid = p.iproductid left join ui.webuser makeruser on makeruser.iuserid = r.ientryuserid left join ui.webuser checkeruser on checkeruser.iuserid = r.iapproveruserid where r.itenantid = :tenantid and cast(r.dtentrystamp at time zone :timeZone as date) between cast(:StartDate as date) and cast(:EndDate as date) limit 10000;'::text WHERE
idashboardqueryid = 84 and itenantid in (14, 15);


--audit report windows

UPDATE ui.dashboardquery SET
vcdashboardquery = 'SELECT r.wname as  "Window Name", r.wdesc as  "Window Description", r.wid "Window ID", makeruser.vcusername as "Maker User", r.dtentrystamp  as "Maker Time Stamp", r.vcremark as "Maker & Checker Remarks", checkeruser.vcusername as "Checker User", r.dtapproverstamp  as "Checker Time Stamp", case when r.vcaction = ''A'' then ''Add'' when r.vcaction = ''M'' then ''Modify'' when r.vcaction = ''X'' then ''Delete'' when r.vcaction = ''N'' then ''No Change'' end as "Action", cast(r.selectexpr as text) as "Select", cast(r.whereexpr as text) as "Where", cast(r.groupbyexpr as text) as "Group By", r.wcount as "Window Count", r.wduration as "Window Duration" FROM ui.observationwindowsuiaudit r left join ui.webuser makeruser on makeruser.iuserid = r.ientryuserid left join ui.webuser checkeruser on checkeruser.iuserid = r.iapproveruserid where r.itenantid = :tenantid and cast(r.dtentrystamp at time zone :timeZone as date) between cast(:StartDate as date) and cast(:EndDate as date) limit 10000;'::text WHERE
idashboardqueryid = 85 and itenantid in (14, 15);


--audit report observations

UPDATE ui.dashboardquery SET
vcdashboardquery = 'SELECT r.oname  as "Observation Name", r.odesc as  "Observation Description", r.oid as "Observation ID", w.wname as "Window Name", makeruser.vcusername as "Maker User", r.dtentrystamp  as "Maker Time Stamp", r.vcremark as "Maker & Checker Remarks", checkeruser.vcusername as "Checker User", r.dtapproverstamp  as "Checker Time Stamp", case when r.vcaction = ''A'' then ''Add'' when r.vcaction = ''M'' then ''Modify'' when r.vcaction = ''X'' then ''Delete'' when r.vcaction = ''N'' then ''No Change'' end as "Action", cast(r.wexpr as text) as "Group By", cast(r.whereexpr as text) as "Where", r.aggregationtype as "Aggregation", r.oduration as "Duration", r.ocount as "Observation Count" FROM ui.observationsuiaudit r left join ui.observationwindowsui w on w.wid = r.wid left join ui.webuser makeruser on makeruser.iuserid = r.ientryuserid left join ui.webuser checkeruser on checkeruser.iuserid = r.iapproveruserid where w.itenantid = :tenantid and cast(r.dtentrystamp at time zone :timeZone as date) between cast(:StartDate as date) and cast(:EndDate as date) limit 10000;'::text WHERE
idashboardqueryid = 86 and itenantid in (14, 15);

--audit report user

UPDATE ui.dashboardquery SET
vcdashboardquery = 'SELECT r.vcusername as "User Name", r.vcfirstname as  "First Name", r.vclastname as "Last Name", r.vcemailid as "Email ID", r.iuserid as  "User ID", r.vcmobile as "Mobile", makeruser.vcusername as "Maker User", r.dtentrystamp  as "Maker Time Stamp", r.vcremark as "Maker & Checker Remarks", checkeruser.vcusername as "Checker User", r.dtapproverstamp  as "Checker Time Stamp", case when r.vcaction = ''A'' then ''Add'' when r.vcaction = ''M'' then ''Modify'' when r.vcaction = ''X'' then ''Delete'' when r.vcaction = ''N'' then ''No Change'' end as "Action", r.vcaddress as "Address", r.vccontact as "Contact", r.vcdesignation as "Designation" FROM ui.webuseraudit r left join ui.webuser makeruser on makeruser.iuserid = r.ientryuserid left join ui.webuser checkeruser on checkeruser.iuserid = r.iapproveruserid where r.iuserauditid in (select webuserauditid from ui.webusermappingaudit where mappingid = :tenantid and mappingtype = ''Tenant'') and cast(r.dtentrystamp at time zone :timeZone as date) between cast(:StartDate as date) and cast(:EndDate as date) limit 10000;'::text WHERE
idashboardqueryid = 87 and itenantid in (14, 15);

--audit report metadata

UPDATE ui.dashboardquery SET
vcdashboardquery = 'SELECT r.vccolumnname as "Parameter Name", r.vcdescription as   "Parameter Description", r.vcdtype as "Data Type", cast(r.vcprefix as text) as "Prefix", r.vcpath as "Path", r.vcroot as "Root Level", r.bml as "ML", r.bscore as "Score", r.bui as "UI", cast(r.config as text) as "Config", makeruser.vcusername as "Maker User", r.dtentrystamp  as "Maker Time Stamp", r.vcremark as "Maker & Checker Remarks", checkeruser.vcusername as "Checker User", r.dtapproverstamp  as "Checker Time Stamp", case when r.vcaction = ''A'' then ''Add'' when r.vcaction = ''M'' then ''Modify'' when r.vcaction = ''X'' then ''Delete'' when r.vcaction = ''N'' then ''No Change'' end as "Action" FROM ui.metadataaudit r left join ui.webuser makeruser on makeruser.iuserid = r.ientryuserid left join ui.webuser checkeruser on checkeruser.iuserid = r.iapproveruserid where r.itenantid = :tenantid and cast(r.dtentrystamp at time zone :timeZone as date) between cast(:StartDate as date) and cast(:EndDate as date) limit 10000;'::text WHERE
idashboardqueryid = 88 and itenantid in (14, 15);


---audit report activity log

UPDATE ui.dashboardquery SET
vcdashboardquery = 'SELECT makeruser.vcusername as "User Name", r.dtactivity  as  "Time stamp", r.vcactivity as "UI", r.vcparameters as "Query Parameter" FROM ui.activitylog r left join ui.webuser makeruser on makeruser.iuserid = r.iuserid where makeruser.iuserid in (select webuserid from ui.webusermapping where mappingid = :tenantid and mappingtype = ''Tenant'') and cast(r.dtactivity at time zone :timeZone as date) between cast(:StartDate as date) and cast(:EndDate as date) limit 50000;'::text WHERE
idashboardqueryid = 89 and itenantid in (14, 15);

--daily merchants onboarded

UPDATE ui.dashboardquery SET
vcdashboardquery = 'SELECT  date(dtentrydatetime) as "Date",   count(1) as "Customers Onboarded"
   	FROM masters.customers where dtentrydatetime between :StartDate and :EndDate and itenantid = :tenantid GROUP BY date(dtentrydatetime) limit 10000;'::text WHERE
idashboardqueryid = 92 and itenantid in (14, 15);

---failed txns 
UPDATE ui.dashboardquery SET
vcdashboardquery = 'select date(dtentrydatetime) as "Date", vcrequestid as "ReqID Failed to Process" from
analytics.scorerequests
WHERE dtentrydatetime between :StartDate and :EndDate and itenantid = :tenantid limit 10000'::text WHERE
idashboardqueryid = 93 and itenantid in (14, 15);
